ETIQUETA_DOLAR = 'dolar service'  # verbose_name del campo: la clave en `cambios`


def _decimal(texto):
    try:
        return Decimal(str(texto).replace(',', '.')).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return None


def reconstruir_historial(apps, schema_editor):
    ConfiguracionService = apps.get_model('precios_service', 'ConfiguracionService')
    HistorialDolar = apps.get_model('precios_service', 'HistorialDolar')
    RegistroAuditoria = apps.get_model('auditoria', 'RegistroAuditoria')

    config = ConfiguracionService.objects.filter(pk=1).first()
    if config is None or HistorialDolar.objects.exists():
        return
    actual = _decimal(config.dolar)
    if actual is None:
        return

    # (valor, desde, usuario_id, username, origen), en orden cronologico.
    filas = []
    registros = RegistroAuditoria.objects.filter(
        app='precios_service', modelo='configuracion de service', accion='editar',
    ).order_by('creado', 'id')
    for registro in registros:
        cambio = (registro.cambios or {}).get(ETIQUETA_DOLAR)
        if not isinstance(cambio, dict):
            continue
        antes, despues = _decimal(cambio.get('antes')), _decimal(cambio.get('despues'))
        if despues is None:
            continue
        if not filas and antes is not None:
            # Lo que regia antes del primer cambio auditado. Desde cuando no se
            # sabe: la fecha de alta de la configuracion si es anterior, y si no
            # un instante antes de ese primer cambio.
            un_instante_antes = registro.creado - datetime.timedelta(seconds=1)
            desde = (
                config.creado
                if config.creado and config.creado < registro.creado
                else un_instante_antes
            )
            filas.append((antes, desde, None, '', 'inicial'))
        filas.append((despues, registro.creado, registro.usuario_id, registro.usuario_username or '', 'manual'))

    if not filas or filas[-1][0] != actual:
        # Sin auditoria, o el valor cambio por fuera de ella (seed, comando):
        # el actual arranca donde dice la configuracion.
        desde = config.actualizado or config.creado or timezone.now()
        if filas and desde <= filas[-1][1]:
            desde = filas[-1][1] + datetime.timedelta(seconds=1)
        filas.append((actual, desde, None, '', 'inicial' if not filas else 'manual'))

    # Vigencias encadenadas y estrictamente crecientes.
    anterior_desde = None
    normalizadas = []
    for valor, desde, usuario_id, username, origen in filas:
        if anterior_desde is not None and desde <= anterior_desde:
            desde = anterior_desde + datetime.timedelta(seconds=1)
        normalizadas.append([valor, desde, usuario_id, username, origen])
        anterior_desde = desde

    objetos = []
    for indice, (valor, desde, usuario_id, username, origen) in enumerate(normalizadas):
        siguiente = normalizadas[indice + 1][1] if indice + 1 < len(normalizadas) else None
        objetos.append(HistorialDolar(
            valor=valor,
            valor_anterior=normalizadas[indice - 1][0] if indice > 0 else None,
            vigente_desde=desde,
            vigente_hasta=siguiente,
            origen=origen,
            usuario_id=usuario_id,
            usuario_username=username,
        ))
    HistorialDolar.objects.bulk_create(objetos)


